TTR & 0.683 & 0.659 & 0.628 & 0.604 \\
Mean Surprisal & \textbf{3.434} & 2.098 & 2.091 & 2.155 \\
Freq.\ Entropy & \textbf{5.767} & 6.599 & 6.631 & 6.682 \\
\bottomrule
\end{tabular}}
\end{center}

